I left out the `last-input` recording. It needs `aap:caps/state-rw`, which is not in this node's `with` clause, so importing it would widen the node's authority. Adding it would require a change to the `with` clause.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{heartbeat-report};

    import aap:caps/http-client@0.1.0;
    import aap:caps/notifier@0.1.0;
    import wasi:clocks/wall-clock@0.2.0;

    export run: func(feed-url: string) -> heartbeat-report;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let now = wall_clock::now();

        let body = http_client::get(&feed_url);
        let fetched = u32::try_from(body.chars().count()).unwrap_or(u32::MAX);

        let message = format!("heartbeat: {} chars fetched at t={}", fetched, now.seconds);
        let notified = notifier::notify(&message);

        // The ensures clause requires notified == true. If the digest channel
        // refuses the message, trap rather than return a report that violates it.
        if !notified {
            panic!("digest notifier refused the message; ensures notified == true cannot hold");
        }

        HeartbeatReport {
            seconds: now.seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

